//! End-to-end parity of `TextPreprocessor` (`get_phones_and_bert` and
//! `preprocess`) against fixtures generated by
//! `parity/e2e/gen_fixtures.py`.
//!
//! Needs `G2PW_MODEL_DIR` (the extracted `G2PWModel_1.1` directory) and
//! `FAST_LANGDETECT_MODEL` (`lid.176.bin`); skipped when either is unset.
//! The `assets` task of `pixi.toml` downloads both into `parity/.cache`.
//! BERT features come from the fake model of `tests/common/e2e_common.rs`.
//!
//! Every output must match exactly, except the inputs listed in `exc`, whose
//! Japanese segments hit a difference between jpreprocess and Open JTalk
//! (see the `exc` docs). The test fails on a new mismatch and on a listed
//! input that now matches. `E2E_VERBOSE=1` prints every mismatch.

#[path = "common/e2e_common.rs"]
mod e2e_common;

use std::collections::{BTreeMap, BTreeSet};
use std::sync::LazyLock;

use e2e_common::{
  FakeBert, full_text_preprocessor, gpb_json, lines, preprocess_json, resolve_methods,
};
use gpt_sovits_text::TextPreprocessor;

static TP: LazyLock<Option<TextPreprocessor<FakeBert>>> = LazyLock::new(full_text_preprocessor);

/// Per `(corpus, mode)`: cases and exact matches (for `preprocess`, one
/// case per text and method).
type Stats = BTreeMap<(String, String), (usize, usize)>;

fn print_stats(name: &str, stats: &Stats) {
  for ((corpus, mode), (n, ok)) in stats {
    eprintln!("{name} {corpus} {mode}: {ok}/{n}");
  }
  let n: usize = stats.values().map(|v| v.0).sum();
  let ok: usize = stats.values().map(|v| v.1).sum();
  eprintln!("{name} total: {ok}/{n}");
}

/// Compares the mismatching keys with the exception list.
fn check_exceptions(name: &str, mismatches: &BTreeSet<String>, expected: &exc::Exceptions) {
  for (cause, keys) in expected {
    eprintln!("{name}: {} known mismatches ({cause})", keys.len());
  }
  let listed: BTreeSet<String> = expected
    .iter()
    .flat_map(|(_, keys)| keys.iter().cloned())
    .collect();
  let new: Vec<&String> = mismatches.difference(&listed).collect();
  let fixed: Vec<&String> = listed.difference(mismatches).collect();
  assert!(
    new.is_empty() && fixed.is_empty(),
    "{name}: unexpected mismatches {new:#?}\nlisted but now matching {fixed:#?}"
  );
}

#[test]
fn get_phones_and_bert_matches_python() {
  let Some(tp) = TP.as_ref() else { return };
  let mut stats = Stats::new();
  let mut mismatches = BTreeSet::new();
  for rec in lines(include_str!("fixtures/e2e/get_phones_and_bert.jsonl")) {
    let corpus = rec["corpus"].as_str().unwrap();
    let text = rec["text"].as_str().unwrap();
    let mode = rec["mode"].as_str().unwrap();
    let got = gpb_json(tp.get_phones_and_bert(text, mode, "v2", false));
    let entry = stats
      .entry((corpus.to_string(), mode.to_string()))
      .or_default();
    entry.0 += 1;
    if got == rec["out"] {
      entry.1 += 1;
    } else {
      if std::env::var("E2E_VERBOSE").is_ok() {
        eprintln!(
          "[{corpus} {mode}] {text:?}\n  want {}\n  got  {got}",
          rec["out"]
        );
      }
      mismatches.insert(format!("{mode} {text}"));
    }
  }
  print_stats("get_phones_and_bert", &stats);
  check_exceptions(
    "get_phones_and_bert",
    &mismatches,
    &exc::get_phones_and_bert(),
  );
}

#[test]
fn preprocess_matches_python() {
  let Some(tp) = TP.as_ref() else { return };
  let mut stats = Stats::new();
  let mut mismatches = BTreeSet::new();
  for rec in lines(include_str!("fixtures/e2e/preprocess.jsonl")) {
    let corpus = rec["corpus"].as_str().unwrap();
    let text = rec["text"].as_str().unwrap();
    let mode = rec["mode"].as_str().unwrap();
    for (method, want) in resolve_methods(&rec["out"]) {
      let got = preprocess_json(tp.preprocess(text, mode, &method, "v2"));
      let entry = stats
        .entry((corpus.to_string(), mode.to_string()))
        .or_default();
      entry.0 += 1;
      if got == want {
        entry.1 += 1;
      } else {
        if std::env::var("E2E_VERBOSE").is_ok() {
          eprintln!("[{corpus} {mode} {method}] {text:?}\n  want {want}\n  got  {got}");
        }
        mismatches.insert(format!("{mode} {method} {text}"));
      }
    }
  }
  print_stats("preprocess", &stats);
  check_exceptions("preprocess", &mismatches, &exc::preprocess());
}

/// Inputs whose output differs from upstream, as `"<mode> <text>"`
/// (`"<mode> <method> <text>"` for `preprocess`), grouped by cause. Every
/// cause is in the Japanese frontend (`japanese::g2p` on a Japanese segment):
///
/// - `KANA_TABLE` and `CHAIN_AFTER_PAUSE` are documented differences between
///   jpreprocess and Open JTalk (`parity/japanese/README.md`,
///   items 6 and 7, and the exception lists of `tests/japanese.rs`).
/// - `UNKNOWN_KANJINUMERIC_GROUP` is not documented in the `japanese` module
///   and is reported as a bug of its MeCab tokenizer port: MeCab groups an
///   unknown word that starts with a `KANJINUMERIC` character (`一`) across
///   the `KANJI` characters that follow (`一部科幻小说`, `一个很长的句子...`
///   become one `記号,数` token without a reading), the port does not.
///   `japanese::g2p("是一部科幻小说", true)` gives `["z", "e"]` upstream
///   and 26 phones in the port. The `japanese` fixtures have no such input.
mod exc {
  pub type Exceptions = Vec<(&'static str, Vec<String>)>;

  const METHODS: [&str; 6] = ["cut0", "cut1", "cut2", "cut3", "cut4", "cut5"];

  fn keys(modes: &[&str], texts: &[&str]) -> Vec<String> {
    modes
      .iter()
      .flat_map(|m| texts.iter().map(move |t| format!("{m} {t}")))
      .collect()
  }

  fn keys_by_method(modes: &[&str], texts: &[&str]) -> Vec<String> {
    let modes: Vec<String> = modes
      .iter()
      .flat_map(|m| METHODS.iter().map(move |c| format!("{m} {c}")))
      .collect();
    let modes: Vec<&str> = modes.iter().map(String::as_str).collect();
    keys(&modes, texts)
  }

  fn long_zh() -> String {
    "这是一个很长的句子".repeat(60) + "。"
  }

  pub fn get_phones_and_bert() -> Exceptions {
    vec![
      // `ヵ`, `ヶ` outside dictionary words (README item 6).
      ("KANA_TABLE", keys(&["ja", "all_ja", "auto"], &["ヵヶ"])),
      // `人` (chain_flag 1) after the pause `实让` in the Japanese segment
      // `得体，着实让人着迷。` that LangSegmenter finds (README item 7).
      (
        "CHAIN_AFTER_PAUSE",
        keys(&["auto", "auto_yue"], &["他的着装很得体，着实让人着迷。"]),
      ),
      (
        "UNKNOWN_KANJINUMERIC_GROUP",
        keys(&["ja", "all_ja"], &["《三体》是一部科幻小说。", &long_zh()]),
      ),
    ]
  }

  pub fn preprocess() -> Exceptions {
    vec![
      ("KANA_TABLE", keys_by_method(&["ja"], &["ヵヶ"])),
      (
        "UNKNOWN_KANJINUMERIC_GROUP",
        keys_by_method(&["ja"], &["《三体》是一部科幻小说。"]),
      ),
    ]
  }
}
